-- US: everything added after the Old Letter / song migration.
-- Generated by "npm run sql:bundle" from supabase/migrations. Safe to paste into the Supabase SQL editor.
-- Wrapped in a transaction: if anything fails, nothing is applied.

begin;

-- ===== 20260103000000_messages_v3.sql =====

-- Messages v3: quick messages, "thinking of you", voice notes, drawings, scheduled delivery (time capsule).
-- Also flips notification privacy to "show the message" by default, as the product intends.

-- 1) New message types ---------------------------------------------------------
alter table public.messages drop constraint messages_message_type_check;
alter table public.messages add constraint messages_message_type_check check (message_type in (
  'love_letter', 'little_note', 'heart_message', 'hug_in_words', 'secret_message', 'old_letter',
  'quick', 'thinking_of_you', 'voice_note', 'drawing'));

-- 2) Attachments (voice note / drawing live in the private storage bucket) and delivery time -
alter table public.messages
  add column attachment_path    text,
  add column attachment_seconds integer,
  add column deliver_at         timestamptz,
  -- the moment a message "arrives" for the recipient: used for ordering
  add column sort_at            timestamptz generated always as (coalesce(deliver_at, created_at)) stored;

alter table public.messages add constraint messages_attachment_check check (
  (message_type in ('voice_note', 'drawing')) = (attachment_path is not null)
  and (attachment_path is not null or attachment_seconds is null)
  and (attachment_path is null or (
        attachment_path ~ ('^' || couple_space_id::text || '/(voice|drawing)/[0-9a-f-]{36}\.(webm|m4a|mp4|ogg|png|jpg)$')
        and (message_type <> 'voice_note' or attachment_path like '%/voice/%')
        and (message_type <> 'drawing' or attachment_path like '%/drawing/%')
        and (attachment_seconds is null or attachment_seconds between 1 and 120)))
);
alter table public.messages add constraint messages_deliver_check check (deliver_at is null or deliver_at > created_at);
create index messages_space_sort_idx on public.messages (couple_space_id, sort_at desc);
create index messages_due_idx on public.messages (deliver_at) where deliver_at is not null and push_status = 'pending';

-- 3) Scheduled messages stay hidden from the recipient until they are due --------------
drop policy messages_select on public.messages;
create policy messages_select on public.messages for select to authenticated
  using (
    couple_space_id = (select public.my_space_id())
    and (
      sender_id = (select auth.uid())
      or (recipient_id = (select auth.uid()) and (deliver_at is null or deliver_at <= now()))
    )
  );

create or replace function public.mark_message_read(p_id uuid) returns timestamptz
language plpgsql security definer set search_path = ''
as $$
declare
  stamp timestamptz;
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  update public.messages set read_at = coalesce(read_at, now())
    where id = p_id and recipient_id = (select auth.uid()) and (deliver_at is null or deliver_at <= now())
    returning read_at into stamp;
  if not found then raise exception 'not_found'; end if;
  return stamp;
end;
$$;

create or replace function public.react_to_message(p_id uuid, p_reaction text) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  if p_reaction is not null and p_reaction not in ('love', 'smile', 'miss', 'thanks', 'hug') then
    raise exception 'invalid_reaction';
  end if;
  update public.messages
    set reaction = p_reaction, reacted_at = case when p_reaction is null then null else now() end
    where id = p_id and recipient_id = (select auth.uid()) and read_at is not null
      and (deliver_at is null or deliver_at <= now());
  if not found then raise exception 'not_found'; end if;
end;
$$;

-- 4) Show the message in notifications by default ---------------------------------
alter table public.user_preferences alter column notification_preview_mode set default 'full';
update public.user_preferences set notification_preview_mode = 'full';

-- 5) send_message v3 -------------------------------------------------------------
drop function public.send_message(text, text, uuid, jsonb);

create function public.send_message(
  p_content text, p_type text, p_client_id uuid,
  p_song jsonb default null, p_attachment jsonb default null, p_deliver_at timestamptz default null
) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid;
  sp_status text;
  rcpt uuid;
  clean text := btrim(coalesce(p_content, ''));
  max_len integer;
  att_path text;
  att_secs integer;
  existing public.messages;
  created public.messages;
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if p_client_id is null then raise exception 'invalid_content'; end if;

  max_len := case p_type
    when 'thinking_of_you' then 100
    when 'little_note' then 280
    when 'voice_note' then 300
    when 'drawing' then 300
    when 'quick' then 500
    when 'heart_message' then 500
    when 'hug_in_words' then 1000
    when 'secret_message' then 1500
    when 'love_letter' then 3000
    when 'old_letter' then 3000
    else null end;
  if max_len is null then raise exception 'invalid_message_type'; end if;
  if clean = '' and p_type = 'voice_note' then clean := 'Voice note'; end if;
  if clean = '' and p_type = 'drawing' then clean := 'Drawing'; end if;
  if char_length(clean) = 0 or char_length(clean) > max_len then raise exception 'invalid_content'; end if;
  if p_song is not null and jsonb_typeof(p_song) <> 'object' then raise exception 'invalid_song'; end if;
  if p_type in ('thinking_of_you', 'voice_note', 'drawing') and p_song is not null then raise exception 'invalid_song'; end if;

  sp := public.my_space_id();
  select status into sp_status from public.couple_spaces where id = sp;
  if sp is null or sp_status <> 'active' then raise exception 'no_active_space'; end if;
  rcpt := public.partner_of(sp);
  if rcpt is null then raise exception 'no_active_space'; end if;

  -- attachment: required for voice notes and drawings, forbidden otherwise
  if p_type in ('voice_note', 'drawing') then
    if p_attachment is null or jsonb_typeof(p_attachment) <> 'object' then raise exception 'invalid_attachment'; end if;
    att_path := p_attachment ->> 'path';
    begin
      att_secs := (p_attachment ->> 'seconds')::integer;
    exception when others then
      raise exception 'invalid_attachment';
    end;
    if att_path is null or position(sp::text || '/' in att_path) <> 1 then raise exception 'invalid_attachment'; end if;
    if not exists (select 1 from storage.objects where bucket_id = 'couple-media' and name = att_path) then
      raise exception 'invalid_attachment';
    end if;
  elsif p_attachment is not null then
    raise exception 'invalid_attachment';
  end if;

  if p_deliver_at is not null then
    if p_type = 'thinking_of_you' or p_deliver_at < now() + interval '1 minute' or p_deliver_at > now() + interval '5 years' then
      raise exception 'invalid_schedule';
    end if;
  end if;

  select * into existing from public.messages where sender_id = uid and client_id = p_client_id;
  if found then
    return jsonb_build_object('message', to_jsonb(existing), 'is_new', false);
  end if;

  perform public.consume_rate_limit('message', 30, interval '10 minutes');
  if p_type = 'thinking_of_you' then
    perform public.consume_rate_limit('ping', 10, interval '10 minutes');
  end if;

  begin
    insert into public.messages (
      couple_space_id, sender_id, recipient_id, content, message_type, client_id, deliver_at,
      attachment_path, attachment_seconds,
      song_track_id, song_title, song_artist, song_preview_url, song_artwork_url, song_start, song_duration
    ) values (
      sp, uid, rcpt, clean, p_type, p_client_id, p_deliver_at,
      att_path, att_secs,
      p_song ->> 'track_id', p_song ->> 'title', p_song ->> 'artist', p_song ->> 'preview_url', p_song ->> 'artwork_url',
      (p_song ->> 'start')::integer, (p_song ->> 'duration')::integer
    )
    returning * into created;
  exception
    when unique_violation then
      select * into existing from public.messages where sender_id = uid and client_id = p_client_id;
      return jsonb_build_object('message', to_jsonb(existing), 'is_new', false);
    when check_violation or invalid_text_representation or numeric_value_out_of_range then
      raise exception '%', case when p_song is not null then 'invalid_song' else 'invalid_attachment' end;
  end;
  return jsonb_build_object('message', to_jsonb(created), 'is_new', true);
end;
$$;

revoke all on function public.send_message(text, text, uuid, jsonb, jsonb, timestamptz) from public, anon, authenticated;
grant execute on function public.send_message(text, text, uuid, jsonb, jsonb, timestamptz) to authenticated;

-- ===== 20260104000000_characters_mood_days.sql =====

-- Characters (each person designs the OTHER), daily mood, and "together since".

-- 1) Together since ---------------------------------------------------------------
alter table public.couple_spaces
  add column together_since date check (together_since is null or together_since >= date '1950-01-01');

create function public.set_together_since(p_date date) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  sp uuid := public.my_space_id();
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  if sp is null then raise exception 'no_active_space'; end if;
  if p_date is not null and (p_date < date '1950-01-01' or p_date > (now() at time zone 'utc')::date + 1) then
    raise exception 'invalid_date';
  end if;
  update public.couple_spaces set together_since = p_date where id = sp;
end;
$$;

-- 2) Characters ---------------------------------------------------------------------
-- One row per designer: the portrait they made of their partner. Both people can read both rows.
create table public.characters (
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  designer_id     uuid not null references auth.users (id) on delete cascade,
  config          jsonb not null,
  updated_at      timestamptz not null default now(),
  primary key (couple_space_id, designer_id)
);
alter table public.characters enable row level security;
create policy characters_select on public.characters for select to authenticated
  using (couple_space_id = (select public.my_space_id()));
grant select on public.characters to authenticated;

create function public.save_character(p_config jsonb) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  sp uuid := public.my_space_id();
  allowed text[] := array['head','hair','hairColor','skinColor','eyes','eyebrows','nose','mouth','glasses','beard',
                          'earrings','freckles','hairAccessories','backgroundColor','eyesColor','eyebrowsColor',
                          'glassesColor','mouthColor'];
  k text;
  v jsonb;
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  if sp is null or (select status from public.couple_spaces where id = sp) <> 'active' then raise exception 'no_active_space'; end if;
  if p_config is null or jsonb_typeof(p_config) <> 'object' or octet_length(p_config::text) > 1200 then
    raise exception 'invalid_character';
  end if;
  for k, v in select * from jsonb_each(p_config) loop
    if not (k = any (allowed)) or jsonb_typeof(v) <> 'string' or (v #>> '{}') !~ '^[A-Za-z0-9]{1,16}$' then
      raise exception 'invalid_character';
    end if;
  end loop;
  perform public.consume_rate_limit('character', 60, interval '1 hour');
  insert into public.characters (couple_space_id, designer_id, config)
  values (sp, (select auth.uid()), p_config)
  on conflict (couple_space_id, designer_id) do update set config = excluded.config, updated_at = now();
end;
$$;

-- 3) Mood: the latest mood of each person ---------------------------------------------
create table public.moods (
  user_id         uuid primary key references auth.users (id) on delete cascade,
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  mood            text not null check (mood in ('happy', 'loved', 'calm', 'excited', 'tired', 'sad', 'stressed')),
  note            text check (note is null or char_length(note) <= 100),
  updated_at      timestamptz not null default now()
);
create index moods_space_idx on public.moods (couple_space_id);
alter table public.moods enable row level security;
create policy moods_select on public.moods for select to authenticated
  using (couple_space_id = (select public.my_space_id()));
grant select on public.moods to authenticated;

-- p_mood null clears it.
create function public.set_mood(p_mood text, p_note text default null) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid := public.my_space_id();
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if sp is null then raise exception 'no_active_space'; end if;
  if p_mood is null then
    delete from public.moods where user_id = uid;
    return;
  end if;
  perform public.consume_rate_limit('mood', 40, interval '1 hour');
  insert into public.moods (user_id, couple_space_id, mood, note)
  values (uid, sp, p_mood, nullif(left(btrim(coalesce(p_note, '')), 100), ''))
  on conflict (user_id) do update
    set couple_space_id = excluded.couple_space_id, mood = excluded.mood, note = excluded.note, updated_at = now();
exception when check_violation then
  raise exception 'invalid_mood';
end;
$$;

-- 4) When someone leaves, their mood and the portraits they made leave with them -------
create or replace function public.handle_member_removed() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  delete from public.moods where user_id = old.user_id;
  delete from public.characters where designer_id = old.user_id and couple_space_id = old.couple_space_id;
  if not exists (select 1 from public.couple_members where couple_space_id = old.couple_space_id) then
    delete from public.couple_spaces where id = old.couple_space_id;
  else
    update public.couple_spaces set status = 'ended' where id = old.couple_space_id;
    update public.couple_invitations set revoked_at = now()
      where couple_space_id = old.couple_space_id and accepted_at is null and revoked_at is null;
  end if;
  return null;
end;
$$;

revoke all on function public.set_together_since(date), public.save_character(jsonb), public.set_mood(text, text) from public, anon, authenticated;
grant execute on function public.set_together_since(date), public.save_character(jsonb), public.set_mood(text, text) to authenticated;

-- ===== 20260105000000_events_story_questions.sql =====

-- Plans & anniversaries, "our story" timeline, and the daily question.

-- Shared rows: the server decides the space and the author, never the client. -----------
create function public.set_shared_row_owner() returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  n bigint;
begin
  new.couple_space_id := public.my_space_id();
  new.created_by := (select auth.uid());
  if new.couple_space_id is null or new.created_by is null
     or (select status from public.couple_spaces where id = new.couple_space_id) <> 'active' then
    raise exception 'no_active_space';
  end if;
  perform public.consume_rate_limit('shared_write', 120, interval '1 hour');
  execute format('select count(*) from %I.%I where couple_space_id = $1', tg_table_schema, tg_table_name)
    into n using new.couple_space_id;
  if n >= 500 then raise exception 'limit_reached'; end if;
  return new;
end;
$$;

-- 1) Plans, anniversaries, birthdays -------------------------------------------------------
create table public.couple_events (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  title           text not null check (char_length(btrim(title)) between 1 and 80),
  note            text check (note is null or char_length(note) <= 300),
  event_date      date not null check (event_date between date '1950-01-01' and date '2100-12-31'),
  repeat_yearly   boolean not null default false,
  kind            text not null default 'plan' check (kind in ('anniversary', 'plan', 'birthday')),
  created_by      uuid not null references auth.users (id) on delete cascade,
  created_at      timestamptz not null default now()
);
create index couple_events_space_date_idx on public.couple_events (couple_space_id, event_date);
create trigger couple_events_owner before insert on public.couple_events for each row execute function public.set_shared_row_owner();

-- 2) Our story: moments worth remembering ----------------------------------------------------
create table public.timeline_entries (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  title           text not null check (char_length(btrim(title)) between 1 and 100),
  note            text check (note is null or char_length(note) <= 1000),
  happened_on     date not null check (happened_on between date '1950-01-01' and date '2100-12-31'),
  photo_path      text,
  created_by      uuid not null references auth.users (id) on delete cascade,
  created_at      timestamptz not null default now(),
  check (photo_path is null or photo_path ~ ('^' || couple_space_id::text || '/story/[0-9a-f-]{36}\.(jpg|png|webp)$'))
);
create index timeline_space_date_idx on public.timeline_entries (couple_space_id, happened_on desc);
create trigger timeline_owner before insert on public.timeline_entries for each row execute function public.set_shared_row_owner();

-- RLS for both: members read; either can edit; only the author deletes.
alter table public.couple_events enable row level security;
alter table public.timeline_entries enable row level security;

create policy events_select on public.couple_events for select to authenticated using (couple_space_id = (select public.my_space_id()));
create policy events_insert on public.couple_events for insert to authenticated
  with check (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
create policy events_update on public.couple_events for update to authenticated
  using (couple_space_id = (select public.my_space_id())) with check (couple_space_id = (select public.my_space_id()));
create policy events_delete on public.couple_events for delete to authenticated
  using (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));

create policy timeline_select on public.timeline_entries for select to authenticated using (couple_space_id = (select public.my_space_id()));
create policy timeline_insert on public.timeline_entries for insert to authenticated
  with check (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
create policy timeline_update on public.timeline_entries for update to authenticated
  using (couple_space_id = (select public.my_space_id())) with check (couple_space_id = (select public.my_space_id()));
create policy timeline_delete on public.timeline_entries for delete to authenticated
  using (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));

grant select, delete on public.couple_events, public.timeline_entries to authenticated;
grant insert (title, note, event_date, repeat_yearly, kind) on public.couple_events to authenticated;
grant update (title, note, event_date, repeat_yearly, kind) on public.couple_events to authenticated;
grant insert (title, note, happened_on, photo_path) on public.timeline_entries to authenticated;
grant update (title, note, happened_on, photo_path) on public.timeline_entries to authenticated;

-- 3) Daily question -----------------------------------------------------------------------------
create table public.question_answers (
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  day             date not null,
  user_id         uuid not null references auth.users (id) on delete cascade,
  answer          text not null check (char_length(btrim(answer)) between 1 and 500),
  created_at      timestamptz not null default now(),
  primary key (couple_space_id, day, user_id)
);
alter table public.question_answers enable row level security;

create function public.i_answered(p_space uuid, p_day date) returns boolean
language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.question_answers where couple_space_id = p_space and day = p_day and user_id = (select auth.uid())) $$;

-- You always see your own answers; your partner's only once you have answered the same question.
create policy answers_select on public.question_answers for select to authenticated
  using (
    user_id = (select auth.uid())
    or (couple_space_id = (select public.my_space_id()) and (select public.i_answered(couple_space_id, day)))
  );
grant select on public.question_answers to authenticated;

create function public.answer_question(p_answer text) returns date
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid := public.my_space_id();
  today date := (now() at time zone 'utc')::date;
  clean text := btrim(coalesce(p_answer, ''));
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if sp is null or (select status from public.couple_spaces where id = sp) <> 'active' then raise exception 'no_active_space'; end if;
  if char_length(clean) = 0 or char_length(clean) > 500 then raise exception 'invalid_content'; end if;
  perform public.consume_rate_limit('answer', 30, interval '1 hour');
  begin
    insert into public.question_answers (couple_space_id, day, user_id, answer) values (sp, today, uid, clean);
  exception when unique_violation then
    raise exception 'already_answered';
  end;
  return today;
end;
$$;

-- Lets the app say "Ben already answered, your turn" without revealing the answer.
create function public.partner_has_answered(p_day date) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.question_answers
    where couple_space_id = (select public.my_space_id()) and day = p_day and user_id <> (select auth.uid()))
$$;

revoke all on function public.answer_question(text), public.partner_has_answered(date), public.i_answered(uuid, date) from public, anon, authenticated;
grant execute on function public.answer_question(text), public.partner_has_answered(date) to authenticated;
-- i_answered is evaluated inside the RLS policy, which runs as the calling role.
grant execute on function public.i_answered(uuid, date) to authenticated;

-- ===== 20260106000000_dreams_coupons_playlist.sql =====

-- Dreams & bucket list, love coupons, and the shared playlist.

-- 1) Dreams -----------------------------------------------------------------------------------
create table public.dreams (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  title           text not null check (char_length(btrim(title)) between 1 and 120),
  note            text check (note is null or char_length(note) <= 500),
  target_date     date check (target_date is null or target_date between date '1950-01-01' and date '2100-12-31'),
  done            boolean not null default false,
  done_at         timestamptz,
  created_by      uuid not null references auth.users (id) on delete cascade,
  created_at      timestamptz not null default now()
);
create index dreams_space_idx on public.dreams (couple_space_id, done, created_at desc);
create trigger dreams_owner before insert on public.dreams for each row execute function public.set_shared_row_owner();

create function public.set_dream_done_at() returns trigger
language plpgsql set search_path = ''
as $$
begin
  if new.done and not old.done then new.done_at := now();
  elsif not new.done then new.done_at := null;
  end if;
  return new;
end;
$$;
create trigger dreams_done_at before update on public.dreams for each row execute function public.set_dream_done_at();

alter table public.dreams enable row level security;
create policy dreams_select on public.dreams for select to authenticated using (couple_space_id = (select public.my_space_id()));
create policy dreams_insert on public.dreams for insert to authenticated
  with check (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
create policy dreams_update on public.dreams for update to authenticated
  using (couple_space_id = (select public.my_space_id())) with check (couple_space_id = (select public.my_space_id()));
create policy dreams_delete on public.dreams for delete to authenticated
  using (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
grant select, delete on public.dreams to authenticated;
grant insert (title, note, target_date) on public.dreams to authenticated;
grant update (title, note, target_date, done) on public.dreams to authenticated;

-- 2) Love coupons ---------------------------------------------------------------------------------
create table public.coupons (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  giver_id        uuid not null references auth.users (id) on delete cascade,
  receiver_id     uuid not null references auth.users (id) on delete cascade,
  title           text not null check (char_length(btrim(title)) between 1 and 80),
  description     text check (description is null or char_length(description) <= 300),
  status          text not null default 'available' check (status in ('available', 'used')),
  created_at      timestamptz not null default now(),
  used_at         timestamptz,
  check (giver_id <> receiver_id)
);
create index coupons_space_idx on public.coupons (couple_space_id, created_at desc);
alter table public.coupons enable row level security;
create policy coupons_select on public.coupons for select to authenticated using (couple_space_id = (select public.my_space_id()));
grant select on public.coupons to authenticated;

create function public.give_coupon(p_title text, p_description text default null) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid := public.my_space_id();
  rcpt uuid;
  row_ public.coupons;
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if sp is null or (select status from public.couple_spaces where id = sp) <> 'active' then raise exception 'no_active_space'; end if;
  rcpt := public.partner_of(sp);
  if rcpt is null then raise exception 'no_active_space'; end if;
  if char_length(btrim(coalesce(p_title, ''))) not between 1 and 80 then raise exception 'invalid_content'; end if;
  if (select count(*) from public.coupons where couple_space_id = sp) >= 500 then raise exception 'limit_reached'; end if;
  perform public.consume_rate_limit('coupon', 20, interval '1 hour');
  insert into public.coupons (couple_space_id, giver_id, receiver_id, title, description)
  values (sp, uid, rcpt, btrim(p_title), nullif(left(btrim(coalesce(p_description, '')), 300), ''))
  returning * into row_;
  return to_jsonb(row_);
end;
$$;

-- Only the person who RECEIVED a coupon can use it.
create function public.redeem_coupon(p_id uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  row_ public.coupons;
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  update public.coupons set status = 'used', used_at = now()
    where id = p_id and receiver_id = (select auth.uid()) and status = 'available'
    returning * into row_;
  if not found then raise exception 'not_found'; end if;
  return to_jsonb(row_);
end;
$$;

-- The giver can take back a coupon that has not been used.
create function public.withdraw_coupon(p_id uuid) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  delete from public.coupons where id = p_id and giver_id = (select auth.uid()) and status = 'available';
  if not found then raise exception 'not_found'; end if;
end;
$$;

-- 3) Shared playlist ----------------------------------------------------------------------------------
create table public.playlist_songs (
  id               uuid primary key default gen_random_uuid(),
  couple_space_id  uuid not null references public.couple_spaces (id) on delete cascade,
  added_by         uuid not null references auth.users (id) on delete cascade,
  song_track_id    text not null check (song_track_id ~ '^[0-9]{1,20}$'),
  song_title       text not null check (char_length(btrim(song_title)) between 1 and 200),
  song_artist      text not null check (char_length(btrim(song_artist)) between 1 and 200),
  song_preview_url text not null check (song_preview_url ~ '^https://([a-z0-9-]+\.)*(itunes\.apple\.com|mzstatic\.com)/[^\s]*$' and char_length(song_preview_url) <= 1000),
  song_artwork_url text check (song_artwork_url is null or (song_artwork_url ~ '^https://([a-z0-9-]+\.)*mzstatic\.com/[^\s]*$' and char_length(song_artwork_url) <= 1000)),
  note             text check (note is null or char_length(note) <= 140),
  created_at       timestamptz not null default now(),
  unique (couple_space_id, song_track_id)
);
alter table public.playlist_songs enable row level security;
create policy playlist_select on public.playlist_songs for select to authenticated using (couple_space_id = (select public.my_space_id()));
grant select on public.playlist_songs to authenticated;

create function public.add_playlist_song(p_song jsonb, p_note text default null) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid := public.my_space_id();
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if sp is null or (select status from public.couple_spaces where id = sp) <> 'active' then raise exception 'no_active_space'; end if;
  if p_song is null or jsonb_typeof(p_song) <> 'object' then raise exception 'invalid_song'; end if;
  if (select count(*) from public.playlist_songs where couple_space_id = sp) >= 300 then raise exception 'limit_reached'; end if;
  perform public.consume_rate_limit('playlist', 40, interval '1 hour');
  begin
    insert into public.playlist_songs (couple_space_id, added_by, song_track_id, song_title, song_artist, song_preview_url, song_artwork_url, note)
    values (sp, uid, p_song ->> 'track_id', p_song ->> 'title', p_song ->> 'artist', p_song ->> 'preview_url', p_song ->> 'artwork_url',
            nullif(left(btrim(coalesce(p_note, '')), 140), ''));
  exception
    when unique_violation then raise exception 'already_added';
    when check_violation or not_null_violation then raise exception 'invalid_song';
  end;
end;
$$;

create function public.remove_playlist_song(p_id uuid) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  delete from public.playlist_songs where id = p_id and added_by = (select auth.uid());
  if not found then raise exception 'not_found'; end if;
end;
$$;

revoke all on function public.give_coupon(text, text), public.redeem_coupon(uuid), public.withdraw_coupon(uuid),
  public.add_playlist_song(jsonb, text), public.remove_playlist_song(uuid) from public, anon, authenticated;
grant execute on function public.give_coupon(text, text), public.redeem_coupon(uuid), public.withdraw_coupon(uuid),
  public.add_playlist_song(jsonb, text), public.remove_playlist_song(uuid) to authenticated;

-- ===== 20260107000000_media_albums.sql =====

-- Private media storage (photos, voice notes, drawings) and photo albums.
--
-- Every file lives under  <couple_space_id>/<kind>/<uuid>.<ext>  in the private "couple-media" bucket,
-- and storage policies only let the two members of that space touch that folder.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('couple-media', 'couple-media', false, 6291456,
        array['image/jpeg', 'image/png', 'image/webp', 'audio/webm', 'audio/mp4', 'audio/ogg', 'audio/mpeg', 'audio/x-m4a'])
on conflict (id) do update
  set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create policy "couple media: members read" on storage.objects for select to authenticated
  using (bucket_id = 'couple-media' and (storage.foldername(name))[1] = (select public.my_space_id())::text);

create policy "couple media: members upload to their folder" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'couple-media'
    and (storage.foldername(name))[1] = (select public.my_space_id())::text
    and (select status from public.couple_spaces where id = (select public.my_space_id())) = 'active'
  );

-- You can only delete files you uploaded yourself.
create policy "couple media: uploader deletes" on storage.objects for delete to authenticated
  using (
    bucket_id = 'couple-media'
    and (storage.foldername(name))[1] = (select public.my_space_id())::text
    and owner_id = (select auth.uid())::text
  );

-- Albums ----------------------------------------------------------------------------------------
create table public.albums (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  title           text not null check (char_length(btrim(title)) between 1 and 80),
  created_by      uuid not null references auth.users (id) on delete cascade,
  created_at      timestamptz not null default now()
);
create index albums_space_idx on public.albums (couple_space_id, created_at desc);
create trigger albums_owner before insert on public.albums for each row execute function public.set_shared_row_owner();

create table public.photos (
  id              uuid primary key default gen_random_uuid(),
  album_id        uuid not null references public.albums (id) on delete cascade,
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  storage_path    text not null,
  caption         text check (caption is null or char_length(caption) <= 200),
  taken_on        date check (taken_on is null or taken_on between date '1950-01-01' and date '2100-12-31'),
  created_by      uuid not null references auth.users (id) on delete cascade,
  created_at      timestamptz not null default now(),
  unique (storage_path),
  check (storage_path ~ ('^' || couple_space_id::text || '/photos/[0-9a-f-]{36}\.(jpg|png|webp)$'))
);
create index photos_album_idx on public.photos (album_id, created_at desc);
create trigger photos_owner before insert on public.photos for each row execute function public.set_shared_row_owner();

-- A photo row must point to a real uploaded file, and to an album of the same couple.
create function public.verify_photo() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if not exists (select 1 from public.albums where id = new.album_id and couple_space_id = new.couple_space_id) then
    raise exception 'invalid_album';
  end if;
  if not exists (select 1 from storage.objects where bucket_id = 'couple-media' and name = new.storage_path) then
    raise exception 'invalid_file';
  end if;
  return new;
end;
$$;
-- Runs after set_shared_row_owner (triggers fire alphabetically): "photos_owner" < "photos_verify".
create trigger photos_verify before insert on public.photos for each row execute function public.verify_photo();

alter table public.albums enable row level security;
alter table public.photos enable row level security;

create policy albums_select on public.albums for select to authenticated using (couple_space_id = (select public.my_space_id()));
create policy albums_insert on public.albums for insert to authenticated
  with check (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
create policy albums_update on public.albums for update to authenticated
  using (couple_space_id = (select public.my_space_id())) with check (couple_space_id = (select public.my_space_id()));
create policy albums_delete on public.albums for delete to authenticated
  using (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));

create policy photos_select on public.photos for select to authenticated using (couple_space_id = (select public.my_space_id()));
create policy photos_insert on public.photos for insert to authenticated
  with check (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
create policy photos_update on public.photos for update to authenticated
  using (couple_space_id = (select public.my_space_id())) with check (couple_space_id = (select public.my_space_id()));
create policy photos_delete on public.photos for delete to authenticated
  using (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));

grant select, delete on public.albums, public.photos to authenticated;
grant insert (title) on public.albums to authenticated;
grant update (title) on public.albums to authenticated;
grant insert (album_id, storage_path, caption, taken_on) on public.photos to authenticated;
grant update (caption, taken_on) on public.photos to authenticated;

commit;
